use jsonl::{arr, b, event, n, s};
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use threat::{
    ThreatRegistry, Violation, check_source_blocks, expand_exposures, expand_footprint,
    expand_product_space, generate_document, load_from_repo, load_threat,
    recompute_id_table_hash, recompute_semantic_contract_hash, scan_claims,
};

fn usage() -> String {
    "usage: threat-check [--root <repo-root>] [--registry <registry-path>] [--write]".into()
}

struct Args {
    root: PathBuf,
    registry: Option<PathBuf>,
    write: bool,
}

fn parse_args() -> Result<Args, String> {
    let mut arguments = std::env::args().skip(1);
    let mut root = None;
    let mut registry = None;
    let mut write = false;
    while let Some(argument) = arguments.next() {
        match argument.as_str() {
            "--root" => {
                if root.is_some() {
                    return Err(format!("--root may be provided only once\n{}", usage()));
                }
                root = Some(PathBuf::from(
                    arguments.next().ok_or("--root requires a value")?,
                ));
            }
            "--registry" => {
                if registry.is_some() {
                    return Err(format!("--registry may be provided only once\n{}", usage()));
                }
                registry = Some(PathBuf::from(
                    arguments.next().ok_or("--registry requires a value")?,
                ));
            }
            "--write" => write = true,
            "-h" | "--help" => return Err(usage()),
            other => return Err(format!("unknown argument {other:?}\n{}", usage())),
        }
    }
    Ok(Args {
        root: root.unwrap_or_else(|| PathBuf::from(".")),
        registry,
        write,
    })
}

fn emit_violation(violation: &Violation) {
    println!(
        "{}",
        event(&[
            ("event", s("threat_violation")),
            ("code", s(&violation.code)),
            ("subject", s(&violation.subject)),
            ("source_anchor", s(&violation.source_anchor)),
            ("replay_command", s(threat::REPLAY_COMMAND)),
            ("outcome", s("fail")),
            ("message", s(&violation.message)),
        ])
    );
    eprintln!(
        "violation[{}] {} {}: {}",
        violation.code, violation.subject, violation.source_anchor, violation.message
    );
}

fn emit_registry_event(registry: &ThreatRegistry, violations: usize, document_matches: bool) {
    println!(
        "{}",
        event(&[
            ("event", s("threat_registry_checked")),
            ("registry", s(&registry.registry.name)),
            ("actor_count", n(registry.actors.len() as i64)),
            ("asset_count", n(registry.assets.len() as i64)),
            ("assumption_count", n(registry.assumptions.len() as i64)),
            ("identity_count", n(registry.identities.len() as i64)),
            (
                "operation_class_count",
                n(registry.operation_classes.len() as i64)
            ),
            (
                "authority_dimension_count",
                n(registry.authority_dimensions.len() as i64)
            ),
            (
                "attenuation_law_count",
                n(registry.attenuation_laws.len() as i64)
            ),
            (
                "external_authority_count",
                n(registry.external_authorities.len() as i64)
            ),
            ("posture_count", n(registry.postures.len() as i64)),
            (
                "deferred_posture_count",
                n(registry.deferred_postures.len() as i64)
            ),
            (
                "exposure_cell_count",
                n(expand_exposures(registry).len() as i64)
            ),
            (
                "footprint_cell_count",
                n(expand_footprint(registry).len() as i64)
            ),
            ("id_table_hash", s(recompute_id_table_hash(registry))),
            (
                "semantic_contract_hash",
                s(recompute_semantic_contract_hash(registry))
            ),
            ("document_matches", b(document_matches)),
            ("violations", n(violations as i64)),
            (
                "outcome",
                s(if violations == 0 { "pass" } else { "fail" })
            ),
        ])
    );
}

fn emit_source_blocks(registry: &ThreatRegistry, root: &Path) {
    let mut ids: Vec<String> = registry
        .source_blocks
        .iter()
        .map(|block| block.id.clone())
        .collect();
    ids.sort();
    for (id, result) in ids.into_iter().zip(check_source_blocks(registry, root)) {
        match result {
            Ok(check) => println!(
                "{}",
                event(&[
                    ("event", s("source_block_checked")),
                    ("source_block", s(check.id)),
                    ("line_count", n(check.line_count as i64)),
                    ("byte_count", n(check.byte_count as i64)),
                    ("fnv1a64", s(check.fnv1a64)),
                    ("outcome", s(check.outcome)),
                ])
            ),
            Err(message) => println!(
                "{}",
                event(&[
                    ("event", s("source_block_checked")),
                    ("source_block", s(id)),
                    ("line_count", n(0)),
                    ("byte_count", n(0)),
                    ("fnv1a64", s("")),
                    ("outcome", s("fail")),
                    ("message", s(message)),
                ])
            ),
        }
    }
}

fn emit_matrices(registry: &ThreatRegistry) {
    for cell in expand_exposures(registry) {
        println!(
            "{}",
            event(&[
                ("event", s("exposure_cell_checked")),
                ("actor", s(&cell.actor_id)),
                ("asset", s(&cell.asset_id)),
                ("disposition", s(&cell.disposition)),
                ("assumption", s(&cell.assumption_id)),
                ("outcome", s("pass")),
            ])
        );
    }
    for cell in expand_product_space(registry) {
        println!(
            "{}",
            event(&[
                ("event", s("posture_cell_checked")),
                ("service_class", s(&cell.service_class)),
                ("role_posture", s(&cell.role_posture)),
                ("continuity_profile", s(&cell.continuity_profile)),
                ("resolution", s(&cell.resolution)),
                ("resolved_by", s(&cell.resolved_by)),
                (
                    "outcome",
                    s(if cell.resolution == "unresolved" {
                        "fail"
                    } else {
                        "pass"
                    })
                ),
            ])
        );
    }
    for posture in &registry.postures {
        println!(
            "{}",
            event(&[
                ("event", s("posture_checked")),
                ("posture", s(&posture.id)),
                ("service_class", s(&posture.service_class)),
                ("role_posture", s(&posture.role_posture)),
                ("continuity_profile", s(&posture.continuity_profile)),
                ("footprint_declaration", s(&posture.footprint_declaration)),
                ("status", s(&posture.status)),
                ("outcome", s("pass")),
            ])
        );
    }
    for cell in expand_footprint(registry) {
        println!(
            "{}",
            event(&[
                ("event", s("authority_row_checked")),
                ("posture", s(&cell.posture_id)),
                ("authority", s(&cell.authority_id)),
                ("cell_status", s(&cell.status)),
                ("on_synchronous_path", b(cell.on_synchronous_path)),
                ("touch_count", n(cell.touch_count as i64)),
                ("sync_path_position", s(&cell.sync_path_position)),
                (
                    "outcome",
                    s(if cell.status == "missing" {
                        "fail"
                    } else {
                        "pass"
                    })
                ),
            ])
        );
    }
    for law in &registry.attenuation_laws {
        println!(
            "{}",
            event(&[
                ("event", s("attenuation_case")),
                ("case_id", s(&law.id)),
                ("class", s(&law.class)),
                ("mutation", s(&law.mutation)),
                ("dimensions", arr(law.dimension_ids.clone())),
                ("negative_fixture", s(&law.negative_fixture)),
                ("outcome", s("pass")),
            ])
        );
    }
    for transition in &registry.binding_transitions {
        println!(
            "{}",
            event(&[
                ("event", s("binding_transition_checked")),
                ("from", s(&transition.from)),
                ("to", s(&transition.to)),
                ("legal", b(transition.legal)),
                ("law", s(&transition.law)),
                ("outcome", s("pass")),
            ])
        );
    }
}

fn emit_claim_scan(registry: &ThreatRegistry, document: &str) -> usize {
    let hits = scan_claims(document, registry);
    for hit in &hits {
        println!(
            "{}",
            event(&[
                ("event", s("claim_scan_flag")),
                ("rule_id", s(&hit.rule_id)),
                ("line", n(hit.line as i64)),
                ("sentence", s(&hit.sentence)),
                ("trust_matrix_conflict", s(&hit.trust_matrix_conflict)),
                ("outcome", s("fail")),
            ])
        );
        eprintln!(
            "claim-scan[{}] {}:{}: {}",
            hit.rule_id,
            registry.registry.document_path,
            hit.line,
            hit.trust_matrix_conflict
        );
    }
    println!(
        "{}",
        event(&[
            ("event", s("claim_scan_completed")),
            ("rules", n(registry.claim_scan_rules.len() as i64)),
            ("flags", n(hits.len() as i64)),
            ("evidence_class", s("lint")),
            (
                "outcome",
                s(if hits.is_empty() { "pass" } else { "fail" })
            ),
        ])
    );
    hits.len()
}

fn run(root: &Path, registry_path: Option<&Path>, write: bool) -> Result<usize, String> {
    let registry = match registry_path {
        Some(path) if path.is_absolute() => load_threat(path),
        Some(path) => load_threat(&root.join(path)),
        None => load_from_repo(root),
    }
    .map_err(|error| error.to_string())?;

    let mut violations = threat::validate_threat(&registry, root);
    let generated = generate_document(&registry, root)?;

    let document_path = root.join(&registry.registry.document_path);
    if write {
        std::fs::write(&document_path, generated.as_bytes())
            .map_err(|error| format!("{}: {error}", document_path.display()))?;
        eprintln!("wrote {}", document_path.display());
    }
    let committed = std::fs::read_to_string(&document_path).unwrap_or_default();
    let document_matches = committed == generated;
    if !document_matches {
        violations.push(Violation {
            code: "document_drift".into(),
            subject: registry.registry.document_path.clone(),
            source_anchor: "§19 G0".into(),
            message: format!(
                "the committed document differs from the regenerated bytes; run `{} --write`",
                threat::REPLAY_COMMAND
            ),
        });
    }

    // Scan the regenerated bytes, not the committed ones: a hand-edited
    // document that drifted is already reported above, and scanning what the
    // registry actually says is what makes the scan reproducible.
    let flags = emit_claim_scan(&registry, &generated);
    if flags > 0 {
        violations.push(Violation {
            code: "claim_exceeds_trust_matrix".into(),
            subject: registry.registry.document_path.clone(),
            source_anchor: "§12.1".into(),
            message: format!("{flags} normative sentence(s) exceed the declared trust matrix"),
        });
    }

    emit_registry_event(&registry, violations.len(), document_matches);
    emit_source_blocks(&registry, root);
    emit_matrices(&registry);
    for violation in &violations {
        emit_violation(violation);
    }
    Ok(violations.len())
}

fn main() -> ExitCode {
    let args = match parse_args() {
        Ok(args) => args,
        Err(error) => {
            eprintln!("{error}");
            return ExitCode::from(2);
        }
    };
    match run(&args.root, args.registry.as_deref(), args.write) {
        Ok(0) => ExitCode::SUCCESS,
        Ok(_) => ExitCode::from(1),
        Err(error) => {
            println!(
                "{}",
                event(&[
                    ("event", s("threat_load_error")),
                    ("root", s(args.root.display().to_string())),
                    ("outcome", s("load_error")),
                    ("message", s(&error)),
                ])
            );
            eprintln!("threat-check load error: {error}");
            ExitCode::from(2)
        }
    }
}
